1	import { type Classification, classifyConsonant } from "./soundType";
2	import {
3		consonants,
4		type ThaiConsonant,
5		ThaiSymbolClass,
6		type ThaiToneMark,
7		type ThaiVowel,
8		type ThaiWord,
9		type ToneValue,
10		toneMarks,
11		vowels,
12		words,
13	} from "./symbols";
14	
15	// ============================================================================
16	// Scene grammar — the annotation shape for every mnemonic-carrying record
17	// ============================================================================
18	// Several facts about Thai lived in this repo only inside mnemonic prose:
19	// which vowels change written form before a final consonant, which glyph
20	// pairs are lookalikes and what actually tells them apart, and where a
21	// symbol's mnemonic stages. Task 2.4 rewrites every one of those strings, so
22	// this module gives the facts fields first. The mnemonic rewrite then only
23	// replaces presentation over data that already exists.
24	
25	// ----------------------------------------------------------------------------
26	// Districts — the non-colour channel for consonant class
27	// ----------------------------------------------------------------------------
28	// Class is encoded twice: colour (consonantClassColor.ts, already shipped)
29	// and a scene district. A district is a PLACE, deliberately height-free,
30	// because tone is pitch and owns the vertical axis (see TONE_MOTION_SOURCE
31	// below) — encoding class as height would spend the tone metaphor twice.
32	// The three places are chosen to be distinguishable by silhouette alone, so
33	// the channel still works under red-green colour vision deficiency, and each
34	// carries a sound-congruent hook for the mnemonics built on it: the high
35	// class is the breathy aspirates and fricatives (a temple's hush), the mid
36	// class is the plain unaspirated stops (flat market haggling), and the low
37	// class's derivable core is the humming sonorants (harbor horns).
38	
39	export const DISTRICTS = ["temple", "market", "harbor"] as const;
40	
41	export type District = (typeof DISTRICTS)[number];
42	
43	const DISTRICT_FOR_CLASS: Record<ThaiSymbolClass, District> = {
44		[ThaiSymbolClass.High]: "temple",
45		[ThaiSymbolClass.Mid]: "market",
46		[ThaiSymbolClass.Low]: "harbor",
47	};
48	
49	/** The class district a consonant of the given class stages in. */
50	export function districtForClass(classType: ThaiSymbolClass): District {
51		return DISTRICT_FOR_CLASS[classType];
52	}
53	
54	// ----------------------------------------------------------------------------
55	// Tone motion — named, never re-declared
56	// ----------------------------------------------------------------------------
57	// The tone-motion vocabulary already ships: TONE_CONTOUR_POINTS in
58	// ToneContourIcon.tsx draws all five contours on every word card. That file
59	// is the single declaration site; annotations refer to a motion by its
60	// ToneValue name and never carry contour data of their own. If the vocabulary
61	// moves, this pointer is the one place scene grammar has to follow it.
62	
63	export const TONE_MOTION_SOURCE =
64		"src/presentation/components/atoms/ToneContourIcon.tsx";
65	
66	export const TONE_MOTION_EXPORT = "TONE_CONTOUR_POINTS";
67	
68	// ----------------------------------------------------------------------------
69	// Conditional vowel forms — extracted from prose into fields
70	// ----------------------------------------------------------------------------
71	// Form strings use "-" for a consonant slot: one dash in an open form (the
72	// initial consonant), two in a with-final form (initial, then final). โ-ะ's
73	// with-final form is "--" — the vowel is written with nothing at all.
74	
75	export interface ConditionalVowelForm {
76		/** Joins ThaiVowel.character exactly, leading space and all. */
77		vowel: string;
78		/** How the vowel is written with no final consonant. */
79		openForm: string;
80		/** How it is written when a final consonant follows. */
81		withFinalForm: string;
82		/** A word showing the with-final form on a real syllable. */
83		example?: string;
84		exceptions?: readonly {
85			finalConsonant: string;
86			form: string;
87			example?: string;
88			note: string;
89		}[];
90	}
91	
92	export const conditionalVowelForms: readonly ConditionalVowelForm[] = [
93		{
94			vowel: "ะ",
95			openForm: "-ะ",
96			withFinalForm: "-ั-",
97			example: "มัน",
98		},
99		{
100			vowel: "เ-ะ",
101			openForm: "เ-ะ",
102			withFinalForm: "เ-็-",
103			example: "เป็น",
104		},
105		{
106			vowel: "แ-ะ",
107			openForm: "แ-ะ",
108			withFinalForm: "แ-็-",
109			example: "แข็ง",
110		},
111		{
112			vowel: "โ-ะ",
113			openForm: "โ-ะ",
114			withFinalForm: "--",
115			example: "กฎ",
116		},
117		{
118			vowel: "เ-าะ",
119			openForm: "เ-าะ",
120			withFinalForm: "-็อ-",
121			example: "น็อต",
122		},
123		{
124			vowel: "เ-อ",
125			openForm: "เ-อ",
