350	
351	// ----------------------------------------------------------------------------
352	// Final-sound behaviour
353	// ----------------------------------------------------------------------------
354	
355	export type FinalSoundBehaviour =
356		| { kind: "final"; sound: string }
357		| { kind: "vowel-syllable"; syllable: "live" | "dead" }
358		| { kind: "not-applicable" };
359	
360	// Short vowels whose open syllable is nonetheless live, because the vowel
361	// carries its own sonorant ending: ำ ends in m, ไ and ใ in the i glide, เ-า
362	// in the o glide. Everything else derives from length: long open syllables
363	// are live, short ones dead.
364	const LIVE_SHORT_VOWELS: readonly string[] = ["ำ", "ไ", "ใ", "เ-า"];
365	
366	function openSyllableLiveness(vowel: ThaiVowel): "live" | "dead" {
367		if (vowel.length === "long") return "live";
368		return LIVE_SHORT_VOWELS.includes(vowel.character) ? "live" : "dead";
369	}
370	
371	// ----------------------------------------------------------------------------
372	// The annotation record
373	// ----------------------------------------------------------------------------
374	
375	export type AnnotationKind = "consonant" | "vowel" | "tone-mark" | "word";
376	
377	export interface SceneAnnotation {
378		kind: AnnotationKind;
379		/** ThaiSymbol.character, or the Thai spelling for a word record. */
380		key: string;
381		romanizedName: string;
382		finalSound: FinalSoundBehaviour;
383		/** Sound-type classification; null where the kind has no class at all. */
384		classification: Classification | null;
385		/** Class district; null for kinds that must not cue a class. */
386		district: District | null;
387		/** The mnemonic's shape binding. Task 2.4 authors these. */
388		shapeCue: string | null;
389		/** The mnemonic's sound binding. Task 2.4 authors these. */
390		soundCue: string | null;
391		carriesTone: boolean;
392		/** One of the five shipped motions, named — never contour data. */
393		toneMotion: ToneValue | null;
394		conditionalForm: ConditionalVowelForm | null;
395	}
396	
397	function consonantAnnotation(consonant: ThaiConsonant): SceneAnnotation {
398		const classification = classifyConsonant(consonant);
399		return {
400			kind: "consonant",
401			key: consonant.character,
402			romanizedName: consonant.nameRomanized,
403			finalSound: { kind: "final", sound: consonant.finalSound },
404			classification,
405			district:
406				classification.state === "classified"
407					? districtForClass(classification.consonantClass)
408					: null,
409			shapeCue: null,
410			soundCue: null,
411			carriesTone: false,
412			toneMotion: null,
413			conditionalForm: null,
414		};
415	}
416	
417	function vowelAnnotation(vowel: ThaiVowel): SceneAnnotation {
418		return {
419			kind: "vowel",
420			key: vowel.character,
421			romanizedName: vowel.name,
422			finalSound: {
423				kind: "vowel-syllable",
424				syllable: openSyllableLiveness(vowel),
425			},
426			classification: null,
427			district: null,
428			shapeCue: null,
429			soundCue: null,
430			carriesTone: false,
431			toneMotion: null,
432			conditionalForm: conditionalFormFor(vowel.character),
433		};
434	}
435	
436	function toneMarkAnnotation(mark: ThaiToneMark): SceneAnnotation {
437		return {
438			kind: "tone-mark",
439			key: mark.character,
440			romanizedName: mark.name,
441			finalSound: { kind: "not-applicable" },
442			classification: null,
443			district: null,
444			shapeCue: null,
445			soundCue: null,
446			carriesTone: true,
447			// The mark's citation motion is its mid-class effect — the tone it is
448			// named for. The full class-dependent table stays on ThaiToneMark.
449			toneMotion: mark.midClassTone,
450			conditionalForm: null,
451		};
452	}
453	
454	function wordAnnotation(word: ThaiWord): SceneAnnotation {
455		return {
456			kind: "word",
457			key: word.name,
458			romanizedName: word.romanization,
459			finalSound: { kind: "not-applicable" },
460			classification: null,
461			district: null,
462			shapeCue: null,
463			soundCue: null,
464			carriesTone: true,
465			toneMotion: word.tone,
466			conditionalForm: null,
467		};
468	}
469	
470	/**
471	 * One annotation per mnemonic-carrying record in symbols.ts: 44 consonants,
472	 * 29 vowels, 4 tone marks, and the mnemonic-bearing words — 82 in all. The
473	 * word and tone-mark records are the nine whose facts have no other home.
474	 */
475	export const sceneAnnotations: readonly SceneAnnotation[] = [
476		...consonants.map(consonantAnnotation),
477		...vowels.map(vowelAnnotation),
478		...toneMarks.map(toneMarkAnnotation),
479		...words.filter((word) => word.mnemonic !== undefined).map(wordAnnotation),
480	];
481	
482	const annotationsByKey = new Map(
483		sceneAnnotations.map((annotation) => [annotation.key, annotation]),
484	);
485	
486	export function annotationFor(key: string): SceneAnnotation | undefined {
487		return annotationsByKey.get(key);
488	}
489	
490	// ----------------------------------------------------------------------------
491	// Validation
492	// ----------------------------------------------------------------------------
493	// Failures name their fields. A refused record must never look like an empty
494	// one — the caller gets the exact list of what is missing and what is wrong.
495	
496	export type Validation =
497		| { ok: true }
498		| { ok: false; missing: readonly string[]; invalid: readonly string[] };
499	
500	function verdict(missing: string[], invalid: string[]): Validation {
501		return missing.length === 0 && invalid.length === 0
502			? { ok: true }
503			: { ok: false, missing, invalid };
504	}
505	
506	function isBlank(value: string | null | undefined): boolean {
507		return value === null || value === undefined || value.trim() === "";
508	}
509	
510	/** The loosely-typed shape validation accepts, so deficient records can be checked. */
511	export interface SceneAnnotationInput {
512		kind: AnnotationKind;
513		district?: District | null;
514		shapeCue?: string | null;
515		soundCue?: string | null;
516		carriesTone?: boolean;
517		toneMotion?: ToneValue | null;
518	}
519	
520	/**
521	 * A record validates only if it binds shape and sound as separate cues, its
522	 * district where it carries a class, and its tone motion where it carries a
523	 * tone. A record binding only shape fails, naming the missing fields.
524	 */
525	export function validateSceneAnnotation(
526		record: SceneAnnotationInput,
527	): Validation {
528		const missing: string[] = [];
529		const invalid: string[] = [];
530	
531		if (isBlank(record.shapeCue)) missing.push("shapeCue");
532		if (isBlank(record.soundCue)) missing.push("soundCue");
533	
534		if (record.kind === "consonant") {
535			if (!record.district) missing.push("district");
536		} else if (record.district) {
537			invalid.push(
538				"district: only a class-bearing record stages in a class district",
539			);
540		}
541	
542		if (record.carriesTone) {
543			if (!record.toneMotion) missing.push("toneMotion");
544		} else if (record.toneMotion) {
545			invalid.push("toneMotion: only a tone-carrying record encodes a motion");
546		}
547	
548		return verdict(missing, invalid);
549	}
550	
551	export function validateConditionalForm(form: {
552		vowel?: string;
553		openForm?: string;
554		withFinalForm?: string;
555	}): Validation {
556		const missing: string[] = [];
557		const invalid: string[] = [];
558	
559		if (isBlank(form.vowel)) missing.push("vowel");
560		if (isBlank(form.openForm)) missing.push("openForm");
561		if (isBlank(form.withFinalForm)) missing.push("withFinalForm");
562		if (
563			!isBlank(form.openForm) &&
564			!isBlank(form.withFinalForm) &&
565			form.openForm === form.withFinalForm
566		) {
567			invalid.push("withFinalForm: declares no change from the open form");
568		}
569	
570		return verdict(missing, invalid);
571	}
572	
573	export function validateConfusablePair(pair: {
574		a?: string;
575		b?: string;
576		feature?: string;
577		detail?: string;
578	}): Validation {
579		const missing: string[] = [];
580		const invalid: string[] = [];
581	
582		if (isBlank(pair.a)) missing.push("a");
583		if (isBlank(pair.b)) missing.push("b");
584		if (isBlank(pair.feature)) {
585			missing.push("feature");
586		} else if (
587			!(DISTINGUISHING_FEATURES as readonly string[]).includes(
588				pair.feature as string,
589			)
590		) {
591			invalid.push(`feature: "${pair.feature}" is not a distinguishing feature`);
592		}
593		if (!isBlank(pair.a) && pair.a === pair.b) {
594			invalid.push("b: a pair must name two different glyphs");
595		}
596	
597		return verdict(missing, invalid);
598	}
