		withFinalForm: "เ-ิ-",
		// The only entry with no example: common Thai has no closed short
		// เ-อะ syllable to cite, so the with-final form stands on the shipped
		// prose alone (the เ-อะ mnemonic states it; task 3.1 teaches it).
	},
	{
		vowel: "-ัว",
		openForm: "-ัว",
		withFinalForm: "-ว-",
		example: "สวน",
	},
	{
		vowel: " ื",
		openForm: "-ือ",
		withFinalForm: "-ื-",
		example: "มืด",
	},
